   "lead": "Un'inchiesta della BBC ha rivelato che meno di 800 scozzesi hanno ricevuto iniezioni per la perdita di peso attraverso il servizio sanitario nazionale (NHS), nonostante questi farmaci siano stati approvati per l'uso già tre anni fa. Lo riferisce BBC News.",
