   "lead": "A Cosenza si registra un'emergenza carburanti, con le scorte esaurite a causa delle proteste e dei timori di un blocco delle forniture. Continua intanto la protesta degli autotrasportatori nel Foggiano, con presidi anche con trattori all'ingresso di Vieste e al casello di Poggio Imperiale. Lo riferisce ANSA.",
