   "orig": "Emomali Rahmon attends CICA summit in Baku",
   "lead": "Il presidente tagiko Emomali Rahmon ha partecipato al summit della Conferenza sull'interazione e le misure di rafforzamento della fiducia in Asia (CICA) a Baku, in Azerbaigian, dove è atteso anche l'adozione della Dichiarazione di Baku. Lo riferisce Asia-Plus.",
