   "sez": "ambiente",
   "titolo": "Il Monte Bianco, il 'tetto d'Europa', perde più di un metro di altezza in un anno",
   "orig": "Mont Blanc, the ‘roof of Europe’, loses more than a metre of height in a year",
   "lead": "La cima del Monte Bianco, in Francia, è ora alta 4.807,47 metri sul livello del mare, oltre un metro in meno rispetto all'anno precedente, secondo un team di geometri. La vetta più alta dell'Europa occidentale fluttua di anno in anno a causa dei cambiamenti climatici alpini: la misurazione del mese scorso risulta comunque 1,88 metri superiore a quella del 2023, quando si erano registrati i livelli più bassi degli ultimi anni.",
   "more": [
    "Il Monte Bianco è la montagna più alta delle Alpi e dell'Europa occidentale; la sua altitudine misurata varia ogni anno perché lo strato di neve e ghiaccio sulla vetta cambia in base a calore, vento e precipitazioni."
   ],
