   "titolo": "Da ingegnere a ristoratrice: ad Anma anche il pane avanzato diventa un cocktail",
   "orig": "Ha studiato ingegneria, poi ha aperto un ristorante dove anche il pane avanzato diventa un cocktail",
   "lead": "Candida Visaggi, laureata in ingegneria con esperienze nelle cucine di Copenaghen e Gabicce Monte, ha aperto il ristorante Anma, dove kombucha, kvass e altri fermentati accompagnano una cucina capace di valorizzare anche gli scarti alimentari, come il pane avanzato trasformato in cocktail. Lo riferisce Gambero Rosso.",
   "more": [
    "Il kombucha e il kvass sono bevande fermentate di origine rispettivamente asiatica e slava, sempre più diffuse nella ristorazione contemporanea per il loro ruolo nella valorizzazione degli scarti e nella riduzione degli sprechi alimentari."
   ],
