   "sez": "salute",
   "titolo": "Solo 1 sudcoreano su 10 si lava le mani nel modo corretto",
   "orig": "Only 1 out of 10 Koreans wash hands in &apos;proper way&apos;",
   "lead": "Secondo un rapporto dell'Agenzia coreana per il controllo e la prevenzione delle malattie, solo l'11,4% dei sudcoreani si lava le mani dopo essere andato in bagno seguendo le modalità raccomandate dalle autorità sanitarie. Il tempo medio dedicato al lavaggio è di 13,9 secondi; l'86% delle persone si lava le mani, ma solo il 46,7% usa il sapone mentre il 39,3% usa solo acqua. Il restante 14% non si lava affatto le mani dopo l'uso del bagno. Lo riferisce The Korea Herald.",
   "more": [
    "Il corretto lavaggio delle mani con sapone per almeno venti secondi è considerato dalle autorità sanitarie una delle misure più efficaci per prevenire la diffusione di infezioni e malattie trasmissibili."
   ],
