   "orig": "Matsurika Kanriden TV Anime Casts Takuya Satō, Hiyori Kōno",
   "lead": "Il sito ufficiale dell'adattamento anime del light novel «Matsurika Kanriden» (The Legend of Bureaucrat Matsurika), scritto da Rinne Ishida, ha annunciato un'ulteriore coppia di doppiatori per la serie, tra cui Takuya Satō e Hiyori Kōno. L'anime debutterà nel gennaio 2027 e andrà in onda su Tokyo MX, MBS, TV Aichi e BS11.",
