   "sez": "salute",
   "titolo": "Dublino, chiuso un negozio di alimenti biologici per un'infestazione di scarafaggi",
   "orig": "Dublin health food shop closed over cockroach infestation",
   "lead": "Un negozio di alimenti biologici e salutistici nel sud di Dublino è stato chiuso dopo che è stata riscontrata un'infestazione attiva di scarafaggi all'interno dei locali. L'esercizio è tra i 12 ristoranti e attività commerciali ai quali l'Autorità per la sicurezza alimentare irlandese (FSAI) ha emesso ordini di chiusura, nell'ambito dei controlli periodici condotti sugli standard igienico-sanitari delle attività che vendono prodotti alimentari in Irlanda. Lo riferisce RTÉ News.",
   "more": [
    "La FSAI è l'autorità irlandese che vigila sulla sicurezza degli alimenti venduti nel paese, effettuando ispezioni periodiche nei negozi e nei ristoranti e potendo disporre la chiusura temporanea delle attività che non rispettano gli standard igienici previsti."
   ],
