   "titolo": "Cupramontana, nelle Marche, la \"Capitale del Verdicchio\" dal 1939",
   "orig": "Marche, è qui che si produce il vino più amato della regione: dal 1939 è la “Capitale del Verdicchio”",
   "lead": "Cupramontana, cittadina dell'entroterra marchigiano, è ufficialmente la capitale del Verdicchio dal 1939, ma vanta una tradizione enologica che risale a tempi molto più antichi. Il borgo è il cuore pulsante della produzione di questo vino, diventato negli anni l'alfiere della regione Marche, che ha saputo imporsi all'attenzione nazionale per la qualità dei propri vini. Lo riferisce Turisti per Caso.",
   "more": [
    "Il Verdicchio è uno dei vini bianchi italiani più noti, prodotto principalmente nelle Marche; le zone di Jesi e di Matelica sono tra le aree di produzione storicamente più rinomate di questo vitigno autoctono."
   ],
