   "sez": "mondo",
   "titolo": "Una donna trasforma il lutto per la sorella in un adesivo salvavita per i seggiolini auto dei bambini",
   "orig": "Woman Who Lost Her Sister Invents a Child’s Car Seat Sticker That Doubles as Hospital Bracelet",
   "lead": "Negli Stati Uniti una donna che ha perso la sorella ha ideato un adesivo per seggiolini auto per bambini che può trasformarsi in un braccialetto ospedaliero in caso di emergenza. Il prodotto, chiamato Roth ID Tag, è pensato per restare attaccato in modo permanente al tessuto del seggiolino: se il bambino deve essere portato d'urgenza in ospedale, una linguetta staccabile dell'adesivo diventa un braccialetto identificativo. Lo riferisce Good News Network.",
   "more": [
    "I seggiolini auto per bambini sono dispositivi di sicurezza obbligatori in molti paesi; strumenti accessori come adesivi o braccialetti identificativi aiutano il personale sanitario a riconoscere rapidamente i piccoli pazienti in situazioni di emergenza."
   ],
