   "sez": "cucina",
   "titolo": "Vitigni resistenti, i parlamentari spingono per l'uso dei Piwi anche nei vini Doc e Docg",
   "orig": "“Via libera all’utilizzo dei Piwi anche nei vini Doc e Docg”. La politica ora accelera sui vitigni resistenti",
   "lead": "I parlamentari Gian Marco Centinaio (Lega) e Antonella Forattini (Pd) hanno annunciato un'interrogazione al ministro Lollobrigida e l'impegno a sbloccare il disegno di legge Patton, fermo da oltre due anni al Senato, per consentire l'utilizzo dei vitigni resistenti Piwi anche nella produzione dei vini Doc e Docg. L'iniziativa punta ad accelerare il percorso normativo che finora ha frenato la diffusione di queste varietà nei disciplinari delle denominazioni più prestigiose. Lo riferisce Gambero Rosso.",
   "more": [
    "I vitigni Piwi sono varietà di vite resistenti alle principali malattie fungine, sviluppate per ridurre l'uso di trattamenti chimici in vigna; il loro impiego nei vini a denominazione protetta è oggetto di dibattito normativo in diversi paesi europei, incluso in Italia."
   ],
