   "id": "z9b04d267",
   "sez": "mondo",
   "titolo": "In Senegal centinaia di persone LGBTQ+ arrestate, molte si nascondono",
   "orig": "LGBTQ+ people go into hiding in Senegal as hundreds are arrested",
   "lead": "Almeno 320 persone sono state arrestate e detenute in Senegal con l'accusa di \"atti contro natura\" da febbraio, dopo l'inasprimento della legge che criminalizza l'omosessualità, secondo un nuovo rapporto di Human Rights Watch citato da The Guardian. Tra gli arrestati, almeno 84 sono stati accusati di \"trasmissione volontaria dell'HIV\" sulla sola base del proprio stato sierologico. Il rapporto denuncia inoltre test HIV forzati e ostacoli all'accesso a una difesa legale adeguata, in un contesto di crescente repressione contro le persone LGBTQ+.",
   "more": [
    "Il Senegal è uno dei numerosi paesi africani in cui l'omosessualità è penalmente perseguita; organizzazioni come Human Rights Watch monitorano regolarmente le condizioni delle minoranze sessuali in contesti dove le leggi discriminatorie si sono inasprite negli ultimi anni."
   ],
