   "id": "zebbce12e",
   "sez": "italia",
   "titolo": "Codice della strada, pugno di ferro sull'Rc auto: multe fino a 4mila euro per chi circola senza polizza",
   "orig": "Codice della strada, pugno di ferro sull’Rc auto: multe fino a 4mila euro per chi circola senza polizza",
   "lead": "La revisione del Codice della strada introduce verifiche mensili sulle banche dati per individuare chi circola senza assicurazione, con multe fino a 4mila euro, trenta giorni di tempo per regolarizzare la posizione e il divieto di marcia a tempo indeterminato per i trasgressori. Tra le altre novità, i ciclisti potranno attraversare sulle strisce pedonali ma dovranno scendere dalla bici in presenza di pedoni, mentre cambiano le regole sulle multe, arrotondate al ribasso tranne per chi guida ubriaco, l'obbligo di esibire patente e libretto viene abolito e il limite di velocità sale sulle autostrade a tre corsie.",
   "more": [
    "Il Codice della strada è l'insieme di norme che regolano la circolazione in Italia, periodicamente aggiornato per adeguarsi a nuove esigenze di sicurezza, mobilità sostenibile e tecnologie di controllo."
   ],
