   "lead": "Un ex arbitro è stato colpito da una sospensione di 15 anni dal mondo del calcio dopo essere stato giudicato colpevole di corruzione. La sanzione, tra le più severe comminate nel settore, pone fine alla carriera dell'uomo nel ruolo di direttore di gara. Lo riferisce Radio Prague International.",
