    "Negli ultimi tempi diversi paesi membri della NATO hanno segnalato avvistamenti di drone non identificati su infrastrutture critiche, episodi che hanno alimentato il dibattito sulla sicurezza aerea e sulle possibili responsabilità statali dietro queste incursioni."
