   "lead": "In totale 278 donne hanno beneficiato di diversi esami medici nell'ambito di una carovana sanitaria dedicata allo screening del cancro al seno, organizzata mercoledì presso l'ospedale locale di Bouficha, nel governatorato di Sousse. L'iniziativa è stata messa in campo dall'Ufficio nazionale della famiglia e della popolazione attraverso una clinica dedicata, con l'obiettivo di favorire la diagnosi precoce della malattia tra le donne della zona. Lo riferisce La Presse de Tunisie.",
