   "lead": "Sam Cosgrove, attaccante dell'Auckland FC in A-League, ha reagito con rabbia a una domanda di un giornalista riguardante una scappatoia regolamentare che ha permesso al club di farlo giocare nella partita di apertura del campionato nonostante una sospensione di due giornate. L'episodio è avvenuto in Australia, dove si disputa il torneo. Lo riferisce ABC News Australia.",
