   "titolo": "Opinione: MyChart diceva che potevo escludere la condivisione dei dati sanitari, ma scoprire come è stato estenuante",
   "orig": "Opinion: MyChart said I could opt out of sharing my health data. Figuring out how was maddening",
   "lead": "In un'opinione pubblicata da STAT, Alex Rosenblat racconta la propria esperienza nel tentativo di rifiutare la condivisione dei propri dati sanitari personali attraverso la piattaforma MyChart, scoprendo un processo complicato che avrebbe richiesto persino l'intervento di un notaio. Lo riferisce STAT.",
   "more": [
    "MyChart è una piattaforma digitale molto usata negli Stati Uniti che permette ai pazienti di accedere alle proprie cartelle cliniche elettroniche, prenotare visite e comunicare con i medici. Le politiche sulla privacy dei dati sanitari digitali sono un tema crescente di dibattito pubblico."
   ],
