   "lead": "L'artista greca d'avanguardia Leda Papaconstantinou ha guidato gli Spetses Players, un gruppo che ha sviluppato una forma sperimentale di performance radicata nel paesaggio, nella comunità locale e nelle realtà sociali in evoluzione dell'isola di Spetses, in Grecia. Il progetto unisce arte performativa e territorio in un approccio originale. Lo riferisce Designboom.",
