    "Spetses è un'isola greca nel Mar Egeo, nota per il suo paesaggio costiero e la sua storia marittima. Le performance d'avanguardia legate al territorio usano spazi non convenzionali, spesso naturali, per coinvolgere comunità locali in esperienze artistiche che mescolano teatro, arte visiva e contesto sociale."
